from pyscipopt import Model, quicksum

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Data
weeks = list(range(1, 9))
demandI = {1:10000, 2:10000, 3:12000, 4:12000, 5:16000, 6:16000, 7:20000, 8:20000}
demandII = {1:6000, 2:7200, 3:8400, 4:10800, 5:10800, 6:12000, 7:12000, 8:12000}
num_skilled = 50
prod_rate_I = 10
prod_rate_II = 6
normal_hours = 40
overtime_hours = 60
wage_skilled = 360
wage_overtime = 540
wage_trainee = 120
wage_new = 240
penalty_I = 0.5
penalty_II = 0.6
max_trainees_per_trainer = 3
total_new_workers = 50

# Decision variables
tr = {}
for t in range(1, 8):
    tr[t] = m.addVar(vtype="I", lb=0, ub=50, name=f"tr_{t}")

trainees = {}
for t in range(1, 8):
    trainees[t] = m.addVar(vtype="I", lb=0, ub=50, name=f"trainees_{t}")

norm_orig = {}
for t in weeks:
    norm_orig[t] = m.addVar(vtype="I", lb=0, ub=50, name=f"norm_orig_{t}")

ot_orig = {}
for t in weeks:
    ot_orig[t] = m.addVar(vtype="I", lb=0, ub=50, name=f"ot_orig_{t}")

norm_new = {}
for t in weeks:
    norm_new[t] = m.addVar(vtype="I", lb=0, ub=50, name=f"norm_new_{t}")

ot_new = {}
for t in weeks:
    ot_new[t] = m.addVar(vtype="I", lb=0, ub=50, name=f"ot_new_{t}")

hI = {}
for t in weeks:
    hI[t] = m.addVar(vtype="C", lb=0, name=f"hI_{t}")

hII = {}
for t in weeks:
    hII[t] = m.addVar(vtype="C", lb=0, name=f"hII_{t}")

backI = {}
for t in weeks:
    backI[t] = m.addVar(vtype="C", lb=0, name=f"backI_{t}")

backII = {}
for t in weeks:
    backII[t] = m.addVar(vtype="C", lb=0, name=f"backII_{t}")

# Helper expressions
def in_training_expr(t):
    if t == 1:
        return tr[1]
    elif t <= 7:
        return tr[t] + tr[t-1]
    else:
        return tr[7]

def trainees_present_expr(t):
    if t == 1:
        return trainees[1]
    elif t <= 7:
        return trainees[t] + trainees[t-1]
    else:
        return trainees[7]

def orig_avail_expr(t):
    return num_skilled - in_training_expr(t)

def cum_new_expr(t):
    if t <= 2:
        return 0
    else:
        return quicksum(trainees[s] for s in range(1, t-1))

# Constraints
# 1. trainees[t] <= 3 * tr[t]
for t in range(1, 8):
    m.addCons(trainees[t] <= max_trainees_per_trainer * tr[t], name=f"max_trainees_{t}")

# 2. Total new workers = 50
m.addCons(quicksum(trainees[t] for t in range(1, 8)) == total_new_workers, name="total_new")

# 3. All original skilled workers work (normal or overtime)
for t in weeks:
    m.addCons(norm_orig[t] + ot_orig[t] == orig_avail_expr(t), name=f"orig_work_{t}")

# 4. All newly trained workers work (normal or overtime)
for t in weeks:
    m.addCons(norm_new[t] + ot_new[t] == cum_new_expr(t), name=f"new_work_{t}")

# 5. Hours split between Food I and Food II
for t in weeks:
    total_hours = normal_hours * (norm_orig[t] + norm_new[t]) + overtime_hours * (ot_orig[t] + ot_new[t])
    m.addCons(hI[t] + hII[t] == total_hours, name=f"hours_{t}")

# 6. Backlog (inventory balance)
for t in weeks:
    prev_backI = backI[t-1] if t > 1 else 0
    prev_backII = backII[t-1] if t > 1 else 0
    m.addCons(backI[t] >= prev_backI + demandI[t] - prod_rate_I * hI[t], name=f"backI_{t}")
    m.addCons(backII[t] >= prev_backII + demandII[t] - prod_rate_II * hII[t], name=f"backII_{t}")

# Objective: minimize total cost
cost_terms = []
for t in weeks:
    # Original skilled workers: normal wage for those working normal + in training
    cost_terms.append(wage_skilled * (norm_orig[t] + in_training_expr(t)))
    # Original skilled workers: overtime wage
    cost_terms.append(wage_overtime * ot_orig[t])
    # Newly trained workers: normal wage
    cost_terms.append(wage_new * norm_new[t])
    # Newly trained workers: overtime wage
    cost_terms.append(wage_overtime * ot_new[t])
    # Trainees wage
    cost_terms.append(wage_trainee * trainees_present_expr(t))
    # Late delivery penalty
    cost_terms.append(penalty_I * backI[t])
    cost_terms.append(penalty_II * backII[t])

m.setObjective(quicksum(cost_terms), "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

