    prev_backII = backII[t-1] if t > 1 else 0
    m.addCons(backI[t] >= prev_backI + demandI[t] - prod_rate_I * hI[t], name=f"backI_{t}")
    m.addCons(backII[t] >= prev_backII + demandII[t] - prod_rate_II * hII[t], name=f"backII_{t}")

