# d[i][t] = delivery of product i in quarter t
d = {}
for i in products:
    for t in quarters:
        d[i][t] = m.addVar(name=f"d_{i}_{t}", lb=0, vtype="C")

# L[i][t] = late (undelivered) units of product i at end of quarter t
L = {}
for i in products:
    for t in quarters:
        L[i][t] = m.addVar(name=f"L_{i}_{t}", lb=0, vtype="C")

# Constraints
for i in products:
    for t in quarters:
        t_idx = t - 1  # 0-based index
        # Flow balance: I[i][t] + d[i][t] = I[i][t-1] + x[i][t]
        lhs = I[i][t] + d[i][t]
        rhs = (I[i][t-1] if t > 1 else 0) + x[i][t]
        m.addCons(lhs == rhs, name=f"flow_{i}_{t}")
