    tw_start[i] = customers_data[i][2][0]
    tw_end[i] = customers_data[i][2][1]

svc = {0: 0}
for i in C:
    svc[i] = svc_time

d = {}
for i in nodes:
    for j in nodes:
        if i != j:
            d[(i, j)] = math.sqrt((coords[i][0] - coords[j][0])**2 + (coords[i][1] - coords[j][1])**2)

M = 2000.0

