    for k in K:
        m.addCons(quicksum(x[(i, j, k)] for j in nodes if j != i) ==
                  quicksum(x[(j, i, k)] for j in nodes if j != i),
                  name=f"flow_{i}_{k}")

# 3. At most one departure from depot per vehicle
for k in K:
    m.addCons(quicksum(x[(0, j, k)] for j in C) <= 1,
              name=f"depot_{k}")

# 4. Time windows for customers
for i in C:
    for k in K:
        m.addCons(t[(i, k)] >= tw_start[i], name=f"tws_{i}_{k}")
        m.addCons(t[(i, k)] <= tw_end[i], name=f"twe_{i}_{k}")

# 5. Time linkage: depot -> customer
for j in C:
    for k in K:
        m.addCons(t[(j, k)] >= t[(0, k)] + d[(0, j)] - M * (1 - x[(0, j, k)]),
                  name=f"tl_0_{j}_{k}")

# 6. Time linkage: customer -> customer
for i in C:
    for j in C:
        if i != j:
            for k in K:
                m.addCons(t[(j, k)] >= t[(i, k)] + svc[i] + d[(i, j)] - M * (1 - x[(i, j, k)]),
                          name=f"tl_{i}_{j}_{k}")

