    for k in K:
        m.addCons(u[(i, k)] >= quicksum(x[(i, j, k)] for j in nodes if j != i),
                  name=f"mtzlb_{i}_{k}")

# 10. Capacity constraint
for k in K:
    m.addCons(quicksum(demand[i] * x[(i, j, k)] for i in C for j in nodes if j != i) <= capacity,
              name=f"cap_{k}")

# Objective: minimize total distance
m.setObjective(quicksum(d[(i, j)] * x[(i, j, k)] for i in nodes for j in nodes if i != j for k in K),
               "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

