import json

# Data: processing times t[i][j] for product i on machine j
t = {(1,1):2, (1,2):3, (1,3):1,
     (2,1):4, (2,2):2, (2,3):3,
     (3,1):3, (3,2):5, (3,3):2}

I = [1, 2, 3]  # products
J = [1, 2, 3]  # machines
K = [1, 2, 3]  # positions in the sequence
BIG_M = 30     # big-M for sequencing (max C + max t = 25 + 5)

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables
# x[i,k] = 1 if product i is in position k
x = {}
for i in I:
    for k in K:
        x[i, k] = m.addVar(vtype="B", name=f"x_{i}_{k}")

# y[i,h] = 1 if product i is scheduled before product h
y = {}
for i in I:
    for h in I:
        if i != h:
            y[i, h] = m.addVar(vtype="B", name=f"y_{i}_{h}")

# C[i,j] = completion time of product i on machine j
C = {}
for i in I:
    for j in J:
        C[i, j] = m.addVar(vtype="C", lb=0, name=f"C_{i}_{j}")

# T = makespan
T = m.addVar(vtype="C", lb=0, name="T")

# Constraint 1: each product assigned to exactly one position
for i in I:
    m.addCons(quicksum(x[i, k] for k in K) == 1, name=f"assign_prod_{i}")

# Constraint 2: each position holds exactly one product
for k in K:
    m.addCons(quicksum(x[i, k] for i in I) == 1, name=f"assign_pos_{k}")

# Constraint 3: for each pair, exactly one ordering
for i in I:
    for h in I:
        if i < h:
            m.addCons(y[i, h] + y[h, i] == 1, name=f"y_pair_{i}_{h}")

# Constraint 4: link y to positions (pos_i = sum k*x[i,k])
for i in I:
    for h in I:
        if i != h:
            pos_i = quicksum(k * x[i, k] for k in K)
            pos_h = quicksum(k * x[h, k] for k in K)
            # If y[i,h]=1 then pos_i < pos_h; if y[i,h]=0 then pos_h < pos_i
            m.addCons(pos_i + 1 - pos_h <= 3 * (1 - y[i, h]), name=f"link1_{i}_{h}")
            m.addCons(pos_h + 1 - pos_i <= 3 * y[i, h], name=f"link2_{i}_{h}")

# Constraint 5: flow (precedence) constraints
for i in I:
    m.addCons(C[i, 1] >= t[i, 1], name=f"flow_m1_{i}")
for i in I:
    for j in [2, 3]:
        m.addCons(C[i, j] >= C[i, j - 1] + t[i, j], name=f"flow_{i}_{j}")

# Constraint 6: sequencing on each machine
for i in I:
    for h in I:
        if i != h:
            for j in J:
                m.addCons(C[h, j] >= C[i, j] + t[h, j] - BIG_M * (1 - y[i, h]),
                          name=f"seq_{i}_{h}_{j}")

# Constraint 7: makespan
for i in I:
    m.addCons(T >= C[i, 3], name=f"makespan_{i}")

# Objective: minimize makespan
m.setObjective(T, "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

