from pyscipopt import Model, quicksum
import json

# Distance matrix (0-indexed: node 0 = location 1)
d = [
    [0,  86, 49, 57, 31, 69, 50],
    [86, 0,  68, 79, 93, 24, 5],
    [49, 68, 0,  16, 7,  72, 67],
    [57, 79, 16, 0,  90, 69, 1],
    [31, 93, 7,  90, 0,  86, 59],
    [69, 24, 72, 69, 86, 0,  81],
    [50, 5,  67, 1,  59, 81, 0]
]

n = 7
nodes = list(range(n))

m = Model("TSP7")
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables: x[i][j] = 1 if edge i->j is in the tour
x = {}
for i in nodes:
    for j in nodes:
        if i != j:
            x[i, j] = m.addVar(vtype="B", name=f"x_{i}_{j}")

# MTZ variables: u[i] = position of node i in the tour (u[0] = 0)
u = {}
for i in nodes:
    if i == 0:
        u[i] = m.addVar(vtype="C", lb=0, ub=0, name=f"u_{i}")
    else:
        u[i] = m.addVar(vtype="C", lb=1, ub=n - 1, name=f"u_{i}")

# Objective: minimize total distance
obj = quicksum(d[i][j] * x[i, j] for i in nodes for j in nodes if i != j)
m.setObjective(obj, "minimize")

# Each node has exactly one outgoing edge
for i in nodes:
    m.addCons(quicksum(x[i, j] for j in nodes if j != i) == 1, name=f"out_{i}")

# Each node has exactly one incoming edge
for j in nodes:
    m.addCons(quicksum(x[i, j] for i in nodes if i != j) == 1, name=f"in_{j}")

# MTZ subtour elimination: u[i] - u[j] + n * x[i][j] <= n - 1
for i in nodes:
    for j in nodes:
        if i != j and i != 0 and j != 0:
            m.addCons(u[i] - u[j] + n * x[i, j] <= n - 1, name=f"mtz_{i}_{j}")

m.optimize()

