from pyscipopt import Model, quicksum
import json

# Data
yards = ['A', 'B']
areas = [1, 2, 3]

min_supply = {'A': 80, 'B': 100}
demand = {1: 55, 2: 75, 3: 50}

dist = {
    ('A', 1): 10, ('A', 2): 5,  ('A', 3): 6,
    ('B', 1): 4,  ('B', 2): 8,  ('B', 3): 15,
}

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables: x[i][j] = tons from yard i to area j
x = {}
for i in yards:
    for j in areas:
        x[i, j] = m.addVar(name=f"x_{i}_{j}", lb=0.0, ub=m.infinity(), vtype="C")

# Supply constraints: each yard supplies at least its minimum
for i in yards:
    m.addCons(quicksum(x[i, j] for j in areas) >= min_supply[i], name=f"supply_{i}")

# Demand constraints: each area receives exactly its demand
for j in areas:
    m.addCons(quicksum(x[i, j] for i in yards) == demand[j], name=f"demand_{j}")

# Objective: minimize total ton-kilometers
obj = quicksum(dist[i, j] * x[i, j] for i in yards for j in areas)
m.setObjective(obj, "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    for i in yards:
        for j in areas:
            print(f"x[{i},{j}] = {m.getVal(x[i,j])}")

