    [10,  0,  5, 10],
    [20,  5,  0,  8],
    [15, 12,  8,  0]
]

m = Model("TSP")
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables
# x[i][j] = 1 if travel from city i to city j (i != j)
x = {}
for i in range(n):
    for j in range(n):
        if i != j:
            x[i, j] = m.addVar(vtype="B", name=f"x_{i}_{j}")

# u[i] for MTZ subtour elimination (u[0] fixed to 0)
u = {}
for i in range(n):
    if i == 0:
        u[i] = m.addVar(vtype="C", lb=0, ub=0, name=f"u_{i}")
    else:
        u[i] = m.addVar(vtype="C", lb=1, ub=n - 1, name=f"u_{i}")

# Constraint 1: each city is entered exactly once
for j in range(n):
    m.addCons(quicksum(x[i, j] for i in range(n) if i != j) == 1, name=f"in_{j}")

# Constraint 2: each city is exited exactly once
for i in range(n):
    m.addCons(quicksum(x[i, j] for j in range(n) if j != i) == 1, name=f"out_{i}")

# Constraint 3: MTZ subtour elimination
for i in range(1, n):
    for j in range(1, n):
        if i != j:
            m.addCons(u[i] - u[j] + n * x[i, j] <= n - 1, name=f"mtz_{i}_{j}")

# Objective: minimize total distance
m.setObjective(quicksum(d[i][j] * x[i, j] for i in range(n) for j in range(n) if i != j), "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
