from pyscipopt import Model, quicksum
import json

# Data
weeks = [1, 2, 3, 4]
demand = {1: 15, 2: 25, 3: 35, 4: 25}
capacity = {1: 30, 2: 40, 3: 45, 4: 20}
prod_cost = {1: 5.0, 2: 5.1, 3: 5.4, 4: 5.5}
storage_cost = 0.2

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables
x = {t: m.addVar(vtype="C", lb=0, ub=capacity[t], name=f"x_{t}") for t in weeks}
I = {t: m.addVar(vtype="C", lb=0, ub=m.infinity(), name=f"I_{t}") for t in weeks}

# Inventory balance: I_t = I_{t-1} + x_t - d_t
for t in weeks:
    if t == 1:
        m.addCons(I[t] == x[t] - demand[t], name=f"bal_{t}")
    else:
        m.addCons(I[t] == I[t-1] + x[t] - demand[t], name=f"bal_{t}")

# Objective: minimize production cost + storage cost
obj = quicksum(prod_cost[t] * x[t] for t in weeks) + storage_cost * quicksum(I[t] for t in weeks)
m.setObjective(obj, "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    for t in weeks:
        print(f"Week {t}: production={m.getVal(x[t]):.2f}, inventory_end={m.getVal(I[t]):.2f}")
